function escHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/**
 * Genera el bloque HTML «También te puede interesar» para una ficha.
 * Devuelve cadena vacía si el slug no tiene relacionados registrados.
 */
export function bloqueRelacionadosHtml(slug: string): string {
  const rels = RELACIONADOS_AUTOCARAVANAS[slug];
  if (!rels || rels.length === 0) return "";
  const items = rels
    .map((r) => {
      const nombre = escHtml(NOMBRES_AUTOCARAVANAS[r] ?? r);
      return `    <li><a href="/autocaravanas/${r}/">${nombre}</a></li>`;
    })
    .join("\n");
  return `<section class="relacionados-autocaravanas">\n  <h2>También te puede interesar</h2>\n  <ul>\n${items}\n  </ul>\n</section>`;
}
